نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
LTIFR این ماه نسبت به ماه قبل 84٪ افزایش داشته. چه اتفاقی افتاده؟ (مدیر HSE — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ltifr"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "ltifr": {
    "prev_month": 1.7,
    "curr_month": 3.12,
    "change_pct": 84
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "safety_incidents",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "incidents": [
    {
      "type": "سقوط از ارتفاع",
      "count": 2,
      "shift": "شیفت شب",
      "lost_days": 12
    },
    {
      "type": "برخورد تجهیزات",
      "count": 1,
      "shift": "شیفت صبح",
      "lost_days": 8
    }
  ],
  "total_lti": 3,
  "root_note": "دو مورد سقوط از ارتفاع در شیفت شب (ساعت ۲ تا ۵ صبح) با نور کم و خستگی"
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
چند ماه است که انتشار ذرات معلق از حد مجاز مجوز بالاتر رفته. علت و هزینهٔ جریمه چقدر است؟ (مدیر HSE — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "permits",
      "description": "مجوزها و انطباق با شرایط",
      "dimensions": [
        "permit_type",
        "authority"
      ],
      "measures": [
        "status",
        "expiry_date",
        "violations"
      ]
    },
    {
      "dataset": "environmental_monitoring",
      "description": "پایش محیط زیست: انتشار، مصرف آب، پسماند",
      "dimensions": [
        "parameter",
        "station",
        "period"
      ],
      "measures": [
        "value",
        "limit",
        "unit"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "permits",
    "filters": {
      "permit_type": "environmental"
    }
  }
}

TOOL_OBSERVATION:
{
  "permit": "مجوز انتشار آلاینده‌ها",
  "authority": "سازمان محیط زیست",
  "limits": {
    "ذرات معلق": "50 میلی‌گرم بر مترمکعب"
  },
  "status": "exceedance",
  "months_over_limit": 4
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "environmental_monitoring",
    "filters": {
      "parameter": "particulate_matter",
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "readings": [
    {
      "month": "ماه 1",
      "value": 61
    },
    {
      "month": "ماه 2",
      "value": 63
    },
    {
      "month": "ماه 3",
      "value": 69
    },
    {
      "month": "ماه 4",
      "value": 60
    }
  ],
  "source": "کورهٔ خشک‌کن (SO2)",
  "avg_exceedance_pct": 30
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
ترکیب ریسک‌های ایمنی و زیست‌محیطی ماه را برای مدیرعامل خلاصه کن. مهم‌ترین اولویت کجاست؟ (مدیر HSE — معدن مس دره‌زار)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    },
    {
      "dataset": "permits",
      "description": "مجوزها و انطباق با شرایط",
      "dimensions": [
        "permit_type",
        "authority"
      ],
      "measures": [
        "status",
        "expiry_date",
        "violations"
      ]
    },
    {
      "dataset": "rehabilitation",
      "description": "وضعیت احیای اراضی تخریب‌شده",
      "dimensions": [
        "area",
        "period"
      ],
      "measures": [
        "disturbed_ha",
        "rehabilitated_ha",
        "target_ha"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "trifr",
      "description": "نرخ بروز حوادث قابل ثبت",
      "formula": "(تعداد حوادث قابل ثبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "rehabilitation_rate",
      "description": "نرخ احیای اراضی",
      "formula": "مساحت احیاشده / مساحت تخریب‌شده",
      "unit": "درصد",
      "dimensions": [
        "area"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ltifr",
      "trifr"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "ltifr": 3.3,
  "trifr": 5.07,
  "near_miss_count": 60
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "permits",
    "filters": {
      "permit_type": "environmental"
    }
  }
}

TOOL_OBSERVATION:
{
  "water_status": "زیر سقف",
  "emission_status": "attention_needed"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "rehabilitation",
    "filters": {
      "period": "this_year"
    }
  }
}

TOOL_OBSERVATION:
{
  "rehabilitation_progress_pct": 48
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
انتشار گازهای گلخانه‌ای خرداد یک‌باره جهش کرد و بعد برگشت. چه رخدادی بود و آیا تکرار می‌شود؟ (مدیر HSE — معدن سنگ‌آهن چادرملو)

زمینهٔ موجود:
