  "data_catalog": [
    {
      "dataset": "emissions",
      "description": "انتشار گازهای گلخانه‌ای و آلاینده‌ها",
      "dimensions": [
        "source",
        "period"
      ],
      "measures": [
        "tons_co2",
        "kg_nox",
        "kg_so2"
      ]
    },
    {
      "dataset": "environmental_monitoring",
      "description": "پایش محیط زیست: انتشار، مصرف آب، پسماند",
      "dimensions": [
        "parameter",
        "station",
        "period"
      ],
      "measures": [
        "value",
        "limit",
        "unit"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "ghg_intensity",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "emissions",
    "filters": {
      "period": "خرداد"
    }
  }
}

TOOL_OBSERVATION:
{
  "spike_source": "آتش‌سوزی باطلهٔ سولفیدی در منطقهٔ انباشت — ۳ روز انتشار SO2 بالا",
  "co2_spike_tons": 240,
  "note": "بعد از مهار آتش، انتشار به حالت عادی برگشت"
}

