زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "water_usage",
      "description": "مصرف و تخلیهٔ آب به تفکیک بخش",
      "dimensions": [
        "section",
        "period"
      ],
      "measures": [
        "intake_m3",
        "discharge_m3",
        "recycled_m3"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "water_intensity",
      "description": "شدت مصرف آب",
      "formula": "مصرف آب / تن محصول",
      "unit": "مترمکعب بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "water_intensity",
